/* Personal match results do not require an opponent roster or change campaign rewards. */
(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(window.UKI18n?.language==='en'?en:ko)}</span>`,T=(en,ko)=>window.UKI18n?.language==='en'?en:ko,actor=()=>window.AccountParity?.account?.id||'',copy=v=>structuredClone(v),choices=new Map(),O=()=>window.MMCampaignOwnership;
const cid=c=>c?.remoteCampaignId||c?.id||'',original=g=>O()?.resolveOwn(g)||null,manageable=(c,g)=>!!O()?.canManage(null,g)&&(!c||ownGangs(c).some(row=>row.id===g?.id)),ownGangs=c=>{const seen=new Set();return (c?.members||[]).map(m=>original(m.gangId||m.gang_id)).filter(g=>g&&!seen.has(g.id)&&seen.add(g.id));},ownList=()=>data.gangs.filter(g=>O()?.owns(g)),key=c=>JSON.stringify([actor(),c?.id||'all']),sourceGang=id=>data.gangs.find(g=>g.id===id),gangName=id=>sourceGang(id)?.name||id;
const personal=g=>Array.isArray(g?.battleRecords)?g.battleRecords:[];
const participants=b=>{const rows=b.participants?.length?b.participants:[{gangId:b.attacker},{gangId:b.defender}],seen=new Set();return rows.map(p=>({...p,gangId:p.gangId||p.gang_id})).filter(p=>p.gangId&&!seen.has(p.gangId)&&seen.add(p.gangId));};
const outcome=(en)=>({win:['Win','승'],draw:['Draw','무'],loss:['Loss','패']}[en]||['Not recorded','미기록']);
const ended=b=>['Played','Completed'].includes(b.status)||b.stage==='completed'||b.rewardsApplied===true;
function aliases(c,g){return new Set([g.id,...(c.members||[]).filter(m=>original(m.gangId)?.id===g.id).map(m=>m.gangId)]);}
function linked(c,b){return window.MMBattlePlay?.linkedReportSession?.(c,b)||(c.sessions||[]).find(s=>s.id===b.sessionId||s.sourceBattleId===b.id||s.legacyBattleId===b.id||s.challengeId==='legacy:'+b.id||(c.automation?.challenges||[]).some(ch=>ch.legacyBattleId===b.id&&s.challengeId===ch.id));}
function derived(c,g){
 const mine=aliases(c,g),seenReports=new Set(),reports=[...(c.battles||[])].reverse().filter(b=>{if(!ended(b))return false;const match=linked(c,b),id=match?'session:'+match.id:'report:'+b.id;if(seenReports.has(id))return false;seenReports.add(id);return true;}),linkedIds=new Set(reports.map(b=>linked(c,b)?.id).filter(Boolean)),rows=[...reports.map(b=>({b,type:'report'})),...(c.sessions||[]).filter(s=>ended(s)&&!linkedIds.has(s.id)).map(b=>({b,type:'session'}))];
 return rows.flatMap(({b,type})=>{const parts=participants(b),ids=new Set(parts.map(p=>p.gangId));if(!parts.some(p=>mine.has(p.gangId)))return [];const winners=[...new Set((b.winners?.length?b.winners:[b.winner]).filter(Boolean))],draw=b.isDraw===true||winners.includes('draw');if(!draw&&(!winners.length||winners.some(id=>!ids.has(id))))return [];return [{id:type+':'+b.id,source:type,sourceId:b.id,campaignId:c.id,canonicalCampaignId:cid(c),campaignName:c.name,result:draw?'draw':winners.some(id=>mine.has(id))?'win':'loss',date:b.date||b.completedAt?.slice(0,10)||b.createdAt?.slice(0,10)||'',opponentName:parts.filter(p=>!mine.has(p.gangId)).map(p=>sourceGang(p.gangId)?.name||p.name||p.gangId).join(', ')||T('Opponent not recorded','상대 미기록'),notes:b.notes||'',title:b.namedScenario||b.scenario||b.name||''}];});
}
function rows(c,g){const result=(c?[c]:data.campaigns.filter(c=>(c.members||[]).some(m=>aliases(c,g).has(m.gangId)))).flatMap(c=>derived(c,g)),linkedKeys=new Set(result.map(r=>r.canonicalCampaignId+':'+r.source+':'+r.sourceId));for(const row of personal(g)){if(!row||typeof row.id!=='string'||!row.id||row.id.length>160||personal(g).filter(item=>item?.id===row.id).length!==1||!['win','draw','loss'].includes(row.result)||c&&row.campaignId!==cid(c))continue;if(row.sourceReportId&&linkedKeys.has(row.campaignId+':report:'+row.sourceReportId)||row.sourceSessionId&&linkedKeys.has(row.campaignId+':session:'+row.sourceSessionId))continue;result.push({...row,source:'manual'});}return result.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
function selected(c,forced){const all=c?ownGangs(c):ownList(),id=forced||choices.get(key(c));return all.find(g=>g.id===id)||all[0]||null;}
function markup(c,forced){const g=selected(c,forced),all=c?ownGangs(c):ownList(),attrs=`data-mr-history data-mr-campaign="${E(c?.id||'')}"${forced?` data-mr-fixed-gang="${E(forced)}"`:''}`;if(!g)return `<section class="panel card mr-history" ${attrs}><h2>${L('Match record','승패 기록')}</h2><p>${L('Join with your own gang to record its results.','본인의 갱으로 참가하면 승패를 기록할 수 있습니다.')}</p></section>`;
 const list=rows(c,g),counts={win:0,draw:0,loss:0};for(const r of list)counts[r.result]++;const can=manageable(c,g),button=(action,en,ko,extra='',kind='')=>`<button type="button" class="btn ${kind}" data-mr-action="${action}" data-mr-gang="${E(g.id)}" ${extra}>${L(en,ko)}</button>`;
 return `<section class="panel card mr-history" ${attrs}><div class="mr-heading"><div><h2>${L('Match record','승패 기록')}</h2><p data-user-text>${E(g.name)}</p></div>${can?button('add','Record result','승패 기록','','primary'):''}</div>${all.length>1&&!forced?`<label class="mr-gang-select">${L('My gang','내 갱')}<select data-mr-select>${all.map(row=>`<option value="${E(row.id)}" ${row.id===g.id?'selected':''} data-user-text>${E(row.name)}</option>`).join('')}</select></label>`:''}<div class="mr-totals" aria-label="${E(T('Match totals','누적 전적'))}">${['win','draw','loss'].map(value=>`<div data-mr-total="${value}"><strong>${counts[value]}</strong>${L(...outcome(value))}</div>`).join('')}</div><p class="mr-caption">${L('Completed campaign matches appear automatically. Record other matches without adding an opponent roster.','완료된 캠페인 경기는 자동 표시됩니다. 상대 갱을 만들지 않고도 다른 경기의 승패를 기록할 수 있습니다.')}</p><div class="mr-list">${list.length?list.map(row=>`<article class="mr-entry" data-mr-entry="${E(row.id)}"><div class="mr-result mr-${row.result}">${L(...outcome(row.result))}</div><div class="mr-copy"><strong data-user-text>${E(row.opponentName)}</strong><small>${E(row.date||'—')}${row.title?' · '+E(row.title):''}</small>${row.notes?`<p data-user-text>${E(row.notes)}</p>`:''}<small>${row.source==='manual'?L('Personal result','직접 입력한 전적'):L('Campaign match','캠페인 경기')}</small></div><div class="mr-actions">${row.source==='manual'&&can?button('edit','Edit','수정',`data-mr-record="${E(row.id)}"`)+button('delete','Delete','삭제',`data-mr-record="${E(row.id)}"`):row.source!=='manual'?button('open','View result','경기 결과 보기',`data-mr-source="${row.source}" data-mr-record="${E(row.sourceId)}" data-mr-source-campaign="${E(row.campaignId)}"`):''}</div></article>`).join(''):`<p class="mr-empty">${L('No match results recorded yet.','아직 기록된 승패가 없습니다.')}</p>`}</div></section>`;
}
function refreshRegion(region){const c=data.campaigns.find(c=>c.id===region.dataset.mrCampaign)||null,fixed=region.dataset.mrFixedGang||'';region.outerHTML=markup(c,fixed);window.UKI18n?.refresh(document.body);}
function today(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),part=type=>parts.find(p=>p.type===type)?.value;return `${part('year')}-${part('month')}-${part('day')}`;}
function openEditor(c,g,recordId,remove=false){
 g=original(g);if(!g||!manageable(c,g))return;const matches=personal(g).filter(row=>row?.id===recordId),current=matches[0];if(recordId&&matches.length!==1)return;const owner=actor(),gangId=g.id,campaignId=c?.id||'',campaignKey=cid(c),baseline=JSON.stringify(g.battleRecords),record=copy(current||{id:crypto.randomUUID(),campaignId:cid(c),result:'win',date:today(),opponentName:'',notes:''});let staged=null;
 const live=()=>{const campaignNow=campaignId?data.campaigns.find(row=>row.id===campaignId):null,gangNow=original(gangId);if(actor()!==owner||!gangNow||campaignId&&(!campaignNow||cid(campaignNow)!==campaignKey)||!manageable(campaignNow,gangNow))throw Error(T('Your gang or access changed. Reopen the record.','내 갱이나 접근 권한이 변경되었습니다. 기록을 다시 여세요.'));if(gangNow.battleRecords!==undefined&&!Array.isArray(gangNow.battleRecords))throw Error(T('The existing match record format needs review before editing.','기존 경기 기록 형식을 확인한 뒤 수정해 주세요.'));const actual=JSON.stringify(gangNow.battleRecords);if(actual!==(staged||baseline))throw Error(T('The match record changed. Reopen it before saving.','경기 기록이 변경되었습니다. 다시 열어 저장하세요.'));return gangNow;};
 const persist=async values=>{const target=live();let changed=!staged;if(!remove){const opponentName=String(values.opponentName||'').trim(),result=values.result,date=values.date,notes=String(values.notes||'');if(!opponentName||opponentName.length>120||!['win','draw','loss'].includes(result)||!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date||notes.length>2000)throw Error(T('Check the opponent, result and date.','상대 이름·승패·날짜를 확인하세요.'));changed=changed||['opponentName','result','date','notes'].some(key=>record[key]!==({opponentName,result,date,notes})[key]);if(changed)Object.assign(record,{opponentName,result,date,notes,createdAt:record.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()});}if(changed){target.battleRecords=remove?personal(target).filter(row=>row?.id!==record.id):[...personal(target).filter(row=>row?.id!==record.id),record];staged=JSON.stringify(target.battleRecords);save();}if(owner)try{await window.AccountParity.ensureSynced();}catch(error){throw Error(T('Saved on this device. Account sync failed; retry to sync the same record.','이 기기에 기록했습니다. 계정 동기화에 실패했으니 같은 기록을 다시 저장해 주세요.')+' '+(error.message||''));}return true;};
 if(remove){showModal(L('Delete match record','경기 기록 삭제'),`<p data-user-text>${E(record.opponentName)} · ${E(record.date)}</p><p>${L('Delete this personal result? Campaign match reports are kept.','직접 입력한 이 전적을 삭제할까요? 캠페인 경기 보고서는 유지됩니다.')}</p>`,T('Delete','삭제'),()=>persist({}));}else{formModal(L(recordId?'Edit match result':'Record match result',recordId?'승패 기록 수정':'승패 기록'),`<p class="wide mr-caption">${L('Manage your gang’s result only. An opponent name is enough.','내 갱의 전적만 기록합니다. 상대는 이름만 입력하면 됩니다.')}</p><label class="wide">${L('My gang','내 갱')}<input value="${E(g.name)}" readonly data-user-text></label><label class="wide">${L('Opponent name','상대 이름')}<input name="opponentName" value="${E(record.opponentName)}" maxlength="120" required data-user-text></label><label>${L('Result','경기 결과')}<select name="result">${['win','draw','loss'].map(value=>`<option value="${value}" ${record.result===value?'selected':''} data-i18n-en="${outcome(value)[0]}" data-i18n-ko="${outcome(value)[1]}">${E(T(...outcome(value)))}</option>`).join('')}</select></label><label>${L('Date','경기 날짜')}<input type="date" name="date" value="${E(record.date)}" required></label><label class="wide">${L('Notes','메모')}<textarea name="notes" rows="3" maxlength="2000" data-user-text>${E(record.notes)}</textarea></label>`,persist,T('Save result','승패 저장'));}const dialog=document.querySelector('.modal-bg .modal');if(dialog){dialog.dataset.personalGangRecord='';dialog.dataset.mrGang=gangId;const form=dialog.querySelector('#modal-form');if(form){form.dataset.personalGangRecord='';form.dataset.mrGang=gangId;}}window.UKI18n?.refresh(document.querySelector('.modal-bg'));
}
document.addEventListener('change',event=>{const input=event.target.closest?.('[data-mr-select]');if(!input)return;const region=input.closest('[data-mr-history]'),c=data.campaigns.find(c=>c.id===region.dataset.mrCampaign)||null;choices.set(key(c),input.value);refreshRegion(region);});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-mr-action]');if(!button)return;event.preventDefault();const region=button.closest('[data-mr-history]'),c=data.campaigns.find(c=>c.id===region?.dataset.mrCampaign)||null,g=original(button.dataset.mrGang),action=button.dataset.mrAction;if(action==='open'){const target=data.campaigns.find(row=>row.id===button.dataset.mrSourceCampaign);if(!target)return;if(button.dataset.mrSource==='report'){data.selectedCampaign=target.id;data.view='campaign';render();window.MMBattlePlay?.openReport(campaign(),button.dataset.mrRecord);}else{const session=target.sessions?.find(row=>row.id===button.dataset.mrRecord);if(session){data.selectedCampaign=target.id;data.view='campaign';sessionDetail(session);}}return;}openEditor(c,g,button.dataset.mrRecord,action==='delete');});
const oldBattles=gangBattles;gangBattles=function(g){return O()?.owns(g)?markup(null,g.id)+oldBattles.apply(this,arguments):oldBattles.apply(this,arguments);};
window.MMMatchRecords={markup,rows,derived,openEditor};
})();
